// Topic state -> mesure panel_state (historique des états du panneau)
// Un message conservé (retained) est le rejeu du dernier état à l'abonnement : on l'ignore.
if (msg.retain === true) { return null; }
const p = msg.payload;
if (!p || typeof p.state !== 'string') { node.warn('state: invalid payload'); return null; }

// Code numérique de l'état : sert au graphique d'états de Grafana
const codes = { OFFLINE: 0, IDLE: 1, MESSAGE_RECEIVED: 2, DISPLAYING: 3, ACK_SENT: 4, CONFIGURING: 5, ERROR: 6 };
const fields = { state_code: codes[p.state] !== undefined ? codes[p.state] : -1 };
if (typeof p.led === 'boolean') { fields.led = p.led ? 1 : 0; }
if (typeof p.uptime_s === 'number') { fields.uptime_s = p.uptime_s; }

msg.measurement = 'panel_state';
msg.payload = [fields, { state: p.state }];
return msg;

// Topic data -> mesure panel_message (messages réellement affichés par le panneau)
const p = msg.payload;
if (!p || typeof p.text !== 'string' || typeof p.id !== 'string' || (p.type !== 'info' && p.type !== 'alert')) {
  node.warn('data: invalid payload'); return null;
}
msg.measurement = 'panel_message';
msg.payload = [{ id: p.id, text: p.text }, { type: p.type }];
return msg;

// Topic ack -> mesure panel_ack (accusés de messages) ou panel_config (accusés de configuration)
const p = msg.payload;
if (!p || typeof p.status !== 'string') { node.warn('ack: invalid payload'); return null; }

if (p.status === 'displayed' && typeof p.id === 'string') {
  const fields = { id: p.id };
  // Délai entre l'envoi de la commande par Node-RED et l'accusé de l'ESP32
  const sent = flow.get('sent') || {};
  if (sent[p.id] !== undefined) {
    fields.latency_ms = Date.now() - sent[p.id];
    delete sent[p.id];
    flow.set('sent', sent);
  }
  msg.measurement = 'panel_ack';
  msg.payload = [fields, { status: 'displayed', type: p.type === 'alert' ? 'alert' : 'info' }];
  return msg;
}

if (p.status === 'configured' && typeof p.display_duration_s === 'number' && typeof p.brightness_pct === 'number') {
  msg.measurement = 'panel_config';
  msg.payload = [{ display_duration_s: p.display_duration_s, brightness_pct: p.brightness_pct }, { status: 'configured' }];
  return msg;
}

node.warn('ack: unknown payload');
return null;

// POST /smartdisplay/cmd : valide la commande, génère l'identifiant et publie sur MQTT

// Les en-têtes CORS sont ajoutés par Node-RED (réglage httpNodeCors de settings.js)
const headers = { 'Content-Type': 'application/json' };
function reply(status, body) { msg.statusCode = status; msg.headers = headers; msg.payload = body; return [null, null, msg]; }

const apiKey = env.get('SMARTDISPLAY_API_KEY');
if (!apiKey) { return reply(503, { error: 'API key not configured on the server' }); }
if (!msg.req || msg.req.headers['x-api-key'] !== apiKey) { return reply(401, { error: 'invalid API key' }); }

let body = msg.payload;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { return reply(400, { error: 'invalid JSON' }); }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) { return reply(400, { error: 'JSON object expected' }); }

if (typeof body.text !== 'string') { return reply(400, { error: "field 'text' missing or not a string" }); }
// L'écran OLED n'affiche que l'ASCII : on retire les accents (é -> e), les autres caractères deviennent '?'
let text = body.text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^\x20-\x7e]/g, '?').trim();
if (text.length === 0) { return reply(400, { error: "field 'text' is empty" }); }
if (text.length > 60) { return reply(400, { error: "field 'text' too long (60 characters maximum)" }); }
if (body.type !== 'info' && body.type !== 'alert') { return reply(400, { error: "field 'type' must be 'info' or 'alert'" }); }

const id = 'msg-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);

// On mémorise l'instant d'envoi (50 commandes au maximum) pour calculer le délai de l'accusé
const sent = flow.get('sent') || {};
sent[id] = Date.now();
const keys = Object.keys(sent);
if (keys.length > 50) { delete sent[keys[0]]; }
flow.set('sent', sent);

const mqttMsg = { topic: 'ariane/smartdisplay/cmd', payload: JSON.stringify({ id: id, text: text, type: body.type }), qos: 0, retain: false };
const influxMsg = { measurement: 'panel_command', payload: [{ id: id, text: text }, { type: body.type }] };
const res = msg;
res.statusCode = 202;
res.headers = headers;
res.payload = { status: 'sent', id: id, text: text, type: body.type };
return [mqttMsg, influxMsg, res];

// POST /smartdisplay/config : valide la configuration et publie sur MQTT

// Les en-têtes CORS sont ajoutés par Node-RED (réglage httpNodeCors de settings.js)
const headers = { 'Content-Type': 'application/json' };
function reply(status, body) { msg.statusCode = status; msg.headers = headers; msg.payload = body; return [null, msg]; }

const apiKey = env.get('SMARTDISPLAY_API_KEY');
if (!apiKey) { return reply(503, { error: 'API key not configured on the server' }); }
if (!msg.req || msg.req.headers['x-api-key'] !== apiKey) { return reply(401, { error: 'invalid API key' }); }

let body = msg.payload;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { return reply(400, { error: 'invalid JSON' }); }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) { return reply(400, { error: 'JSON object expected' }); }

const config = {};
const d = body.display_duration_s;
const b = body.brightness_pct;
if (d !== undefined && d !== null) {
  if (!Number.isInteger(d)) { return reply(400, { error: "field 'display_duration_s' must be an integer" }); }
  if (d < 1 || d > 300) { return reply(400, { error: "field 'display_duration_s' out of range (1 to 300)" }); }
  config.display_duration_s = d;
}
if (b !== undefined && b !== null) {
  if (!Number.isInteger(b)) { return reply(400, { error: "field 'brightness_pct' must be an integer" }); }
  if (b < 0 || b > 100) { return reply(400, { error: "field 'brightness_pct' out of range (0 to 100)" }); }
  config.brightness_pct = b;
}
if (Object.keys(config).length === 0) { return reply(400, { error: "no known field (display_duration_s, brightness_pct)" }); }

const mqttMsg = { topic: 'ariane/smartdisplay/config', payload: JSON.stringify(config), qos: 0, retain: false };
const res = msg;
res.statusCode = 202;
res.headers = headers;
res.payload = { status: 'sent', config: config };
return [mqttMsg, res];
